import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import "@/server/services/notification-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

const PAST = "2026-01-01T00:00:00.000Z";
const FUTURE = "2026-12-31T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");
const later = (ms: number): Date => new Date(NOW.getTime() + ms);

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

async function insertIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; assigneeId: Tenant["userIds"]["member"] | null; dueAt: string | null }>,
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, overrides),
    tenant.userIds.owner,
    number,
  );
}

function collectOverdue(): { seen: string[]; off: () => void } {
  const seen: string[] = [];
  const off = subscribe("issue.overdue", (payload) => {
    seen.push(payload.issueId);
  });
  return { seen, off };
}

describe("verify overdue + closing fixes", () => {
  it("announces only open, live, strictly past-due issues, including in a brand-new workspace", async () => {
    const tenant = await createTenant("v-select"); // no organization_usage row on purpose
    const open = await insertIssue(tenant, { dueAt: PAST, assigneeId: tenant.userIds.member });
    const canceled = await insertIssue(tenant, { dueAt: PAST });
    await issueRepo.setIssueStatus(tenant.org.id, canceled.id, "canceled");
    const done = await insertIssue(tenant, { dueAt: PAST });
    await issueRepo.setIssueStatus(tenant.org.id, done.id, "done");
    const exact = await insertIssue(tenant, { dueAt: toIsoTimestamp(NOW) });
    const future = await insertIssue(tenant, { dueAt: FUTURE });
    const archived = await insertIssue(tenant, { dueAt: PAST });
    await issueRepo.archiveIssue(tenant.org.id, archived.id);

    const { seen, off } = collectOverdue();
    try {
      await runOverdueIssueJob(NOW);
      expect(seen).toContain(open.id);
      expect(seen).not.toContain(canceled.id);
      expect(seen).not.toContain(done.id);
      expect(seen).not.toContain(exact.id);
      expect(seen).not.toContain(future.id);
      expect(seen).not.toContain(archived.id);
    } finally {
      off();
    }
  });

  it("does not announce issues from a deleted workspace", async () => {
    const tenant = await createTenant("v-deleted");
    const issue = await insertIssue(tenant, { dueAt: PAST });
    await orgRepo.archiveOrg(tenant.org.id);

    const { seen, off } = collectOverdue();
    try {
      await runOverdueIssueJob(NOW);
      expect(seen).not.toContain(issue.id);
    } finally {
      off();
    }
  });

  it("re-announces after a sweep finds the issue settled (closed, then reopened while past due)", async () => {
    const tenant = await createTenant("v-relapse");
    const issue = await insertIssue(tenant, { dueAt: PAST });

    const { seen, off } = collectOverdue();
    const count = (): number => seen.filter((id) => id === issue.id).length;
    try {
      await runOverdueIssueJob(NOW);
      expect(count()).toBe(1);
      await runOverdueIssueJob(later(60_000));
      expect(count()).toBe(1);

